#!/usr/bin/env python3
"""Patch: 7-day hourly chart with spike filtering."""

import base64, json, os, subprocess

ROOT = os.path.expanduser("~/insight-dashboards")

FILES = json.loads("""{"dashboards/youtube/cache.py": "", "dashboards/server.py": "", "frontend/youtube-shorts/index.html": ""}""")

for rel, b64 in FILES.items():
    dest = os.path.join(ROOT, rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"  wrote {rel}")

subprocess.run(["git", "-C", ROOT, "add", "-A"], check=True)
r = subprocess.run(["git", "-C", ROOT, "commit", "-m", "feat: 7-day hourly chart with spike filtering"], check=False)
if r.returncode not in (0, 1):
    raise SystemExit(f"git commit failed: {r.returncode}")
subprocess.run(["git", "-C", ROOT, "push", "origin", "HEAD"], check=True)
print("Done.")
